// Genera messages/es-ES.d.json.ts (mismo formato que next-intl) para tipar claves y argumentos
// sin tener que arrancar next dev. Uso: pnpm i18n:types
import { readFileSync, writeFileSync } from "node:fs";

const src = "messages/es-ES.json";
const json = JSON.parse(readFileSync(src, "utf8"));
const out =
  "// This file is auto-generated by next-intl, do not edit directly.\n" +
  "// See: https://next-intl.dev/docs/workflows/typescript#messages-arguments\n\n" +
  `declare const messages: ${JSON.stringify(json, null, 2)};\nexport default messages;\n`;
writeFileSync("messages/es-ES.d.json.ts", out);
